INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H640', 'NORMA', 'S', 'El tipo de transaccion debe indicarse con codificacion numerica segun instructivo. Donde 1= Compra;2= Nota Debito Compras;3= Nota de Credito Compras;4= Venta;5= Nota de Debito Ventas;6= Nota de credito Ventas', 'E', '[C6] = {1,2,3,4,5,6}');
INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H641', 'NORMA', 'S', 'Valores transados debe indicarse con codificacion numerica segun instructivo. Donde 1= Efectivo; 2= Cheque Viajero. 3=Canje Valores extranjeros', 'E', '[C7] = {1,2,3}');
INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H642', 'NORMA', 'S', 'La fecha de operacion debe estar dentro del año comercial que se esta declarando con formato dd/mm/aaaa y debe ser distinta de blanco', 'E', '01.01.AT-1 â‰¤ [C8] â‰¤ 31.12.AT-1');
INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H643', 'NORMA', 'S', 'El tipo de documento debe indicarse con codificacion numerica segun instructivo. 1,2,3,4,5,6,7,8', 'E', '[C11] = {1,2,3,4,5,6,7,8}');
INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H644', 'NORMA', 'S', 'El codigo de moneda transada debe indicarse con codificacion  segun instructivo, publicado en el suplemento.', 'E', '[C13] = {Codificacion publicada en el suplemento de declaraciones Juradas del SII para codigos de monedas} ');
INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H645', 'NORMA', 'S', 'Debe existir al menos un valor mayor que cero en las columnas Compras, Ventas y no pueden tener valores negativos (y ambas columnas deben ser excluyentes). Debe existir un valor mayor que cero en la columna Tipo de cambio', 'E', 'Si {C14>0 --> C15=0  o  Si C15>0 --> C14=0}   .y.[C16] >0 ');
INSERT INTO BSCL."BSCL.Normativa.BD::DOC.Validacion" ("Esquema", "Version", "Codigo", "Tipo", "Activa", "Descripcion", "Severidad", "Formula") VALUES('DJ1870', '2020', 'H647', 'NORMA', 'S', 'Se debe verificar que si existe valor en el  campo Codigo Pais sea consistente con las instrucciones de la declaracion jurada respectiva u oficios de S.I.I y en caso de no existir valor en el campo Codigo Pais exista Rut informado asociado (extranjero).', 'E', 'Si [C4] <> blanco; entonces [C4]= Codigo Pais= {Tabla Codigo Pais Anexo correspondiente} y. si [C4] = blanco; entonces [C1] <> blanco');
