SET SCHEMA BSCL;


-- DROP TABLE BSCL."BSCL.Normativa.BD::TRI.DatosDJ1870";
DROP TABLE BSCL."BSCL.Normativa.BD::TRI.DatosDJ1870";

CREATE TABLE BSCL."BSCL.Normativa.BD::TRI.DatosDJ1870" (
	ID BIGINT NOT NULL,
	"IdDocumento" BIGINT NOT NULL,
	"VboUsuario" CHAR(1) NOT NULL,
	"Observaciones" NVARCHAR(250) NOT NULL,
	"FuenteDatos" NVARCHAR(40) NOT NULL,
	"DatosPersonaRut" NVARCHAR(40) NOT NULL,
	"DatosPersonaDV" NVARCHAR(10) NOT NULL,
	"DatosPersonaIndentificadorExtranjero" NVARCHAR(40) NOT NULL,
	"DatosPersonaPaisOtorganteIdentificador" NVARCHAR(10) NOT NULL,
	"DatosPersonaNombreRazonSocial" NVARCHAR(100) NOT NULL,
	"TipoTransaccionDJ" NVARCHAR(100) NOT NULL,
	"ValoresTransados"  NVARCHAR(10) NOT NULL,
	"FechaTransaccionDia" NVARCHAR(10) NOT NULL,
	"FechaTransaccionMes" NVARCHAR(10) NOT NULL,
	"FechaTransaccionAnio" NVARCHAR(10) NOT NULL,
	"DocumentoTipoDocumento" NVARCHAR(100) NOT NULL,
	"DocumentoNumero" BIGINT,
	"CodigoMonedaTransada" NVARCHAR(10) NOT NULL,
	"MontoCompras" DECIMAL(26,8) DEFAULT 0 NOT NULL,
	"MontoVentas" DECIMAL(26,8) DEFAULT 0 NOT NULL,
	"TipoCambio" DECIMAL(26,8) NOT NULL,
	"FechaDocumento" DATE,
	"IdCliente" BIGINT,
	"IdPortafolio" BIGINT,
	"IndNacionalidad" NVARCHAR(1),
	"Paridad" DECIMAL(26,8) NOT NULL,
	"LineaFactura" BIGINT,
	PRIMARY KEY (ID)
);


